/**
 * 循環播放按鈕插件
 */

import type { MpvPlugin } from '../../core/types/plugin';
import { ControlPlugin, ControlPluginOptions } from '../base/ControlPlugin';
import { loopIcon } from '../../renderer/icons';
import styles from './styles.css?inline';

export interface LoopButtonPluginOptions extends ControlPluginOptions {
    position?: 'left' | 'right';
    order?: number;
}

export const LoopButtonPlugin: MpvPlugin<LoopButtonPluginOptions> = {
    name: 'loopButton',
    version: '1.0.0',
    styles,

    install(player, options = {}) {
        return new LoopButtonManager(player, {
            position: options.position ?? 'right',
            order: options.order ?? 10,
        });
    },
};

export class LoopButtonManager extends ControlPlugin<Required<LoopButtonPluginOptions>> {
    readonly name = 'loopButton';

    protected createEl(): HTMLElement {
        const btn = document.createElement('button');
        btn.className = 'vp-btn vp-loop-btn';
        btn.title = '循環播放 (L)';
        btn.innerHTML = `<span class="vp-icon-loop">${loopIcon}</span>`;

        this.on(btn, 'click', (e) => {
            e.stopPropagation();
            this.player.loop = !this.player.loop;
            this.updateState();
        });

        // 監聯 loop 狀態變化事件（來自外部 API 或其他 UI）
        this.onPlayer('loopchange', () => this.updateState());
        // 監聽相關事件更新狀態
        this.onPlayer('play', () => this.updateState());
        this.onPlayer('loadedmetadata', () => this.updateState());

        // 初始化狀態
        this.updateState();

        return btn;
    }

    private updateState(): void {
        if (this.el) {
            this.el.classList.toggle('active', this.player.loop);
        }
    }
}

